$root = (Resolve-Path "$PSScriptRoot\..\..").Path; $legacyData = Join-Path $env:USERPROFILE '.avatarkit'; if (-not $env:AVATARKIT_HOME -or $env:AVATARKIT_HOME -eq $legacyData) { $env:AVATARKIT_HOME = Join-Path $root 'backend\.avatarkit' }; foreach ($name in 'backend.pid','frontend.pid') { $file = Join-Path $env:AVATARKIT_HOME $name; if (Test-Path $file) { $id = Get-Content $file; $proc = Get-Process -Id $id -ErrorAction SilentlyContinue; if ($proc) { Stop-Process -Id $id -Force }; Remove-Item $file -Force } }
